-- public.wild_form_roll(p_species text, p_colour double precision, p_size double precision, OUT form_colour boolean, OUT form_size text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.wild_form_roll(p_species text, p_colour double precision, p_size double precision, OUT form_colour boolean, OUT form_size text)
 RETURNS record
 LANGUAGE sql
 STABLE
AS $function$
  select not sd.monster and p_colour < 1 / colour_form_odds(),
         case when sd.monster then null
              when p_size < 1 / (2 * size_form_odds()) then 'large'
              when p_size < 1 / size_form_odds() then 'small' end
    from species_def sd where sd.id = p_species
$function$
